parameters.text:
=Analyse the following project requirements and pre-computed infrastructure calculations, then produce the structured infrastructure sizing recommendation.

DATA:
{{ $json.ai_payload }}

parameters.jsCode:
const calc = $('Validate & Calculate Sizing').first().json;
const input = calc.input;
const c = calc.calculated;
const ai = $input.first().json.output || {};

const esc = (v) => String(v === undefined || v === null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const rows = (arr) => (Array.isArray(arr) ? arr : []).map(x => '<li>' + esc(x) + '</li>').join('');

const yearRows = (c.yearly_capacity || []).map(y =>
  '<tr><td>Year ' + y.year + '</td><td>' + y.employees + '</td><td>' + y.daily_data_tb +
  '</td><td>' + y.annual_data_tb + '</td><td>' + y.cumulative_data_tb + '</td></tr>').join('');

const bom = (ai.bom || []);
const bomRows = bom.map(b =>
  '<tr><td>' + esc(b.category) + '</td><td>' + esc(b.item) + '</td><td>' + esc(b.quantity) +
  '</td><td>' + esc(b.minimum_specification) + '</td><td>' + esc(b.recommended_specification) +
  '</td><td>' + esc(b.purpose) + '</td><td>' + esc(b.assumption) + '</td></tr>').join('');

const kv = (label, val) => '<tr><td>' + esc(label) + '</td><td>' + esc(val) + '</td></tr>';

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:960px;margin:0 auto;color:#1a1a1a;">
  <h1 style="border-bottom:3px solid #ff6d5a;padding-bottom:8px;">Project Infrastructure Sizing Report</h1>
  <p><strong>Project:</strong> ${esc(input.project_no)} &nbsp;|&nbsp; <strong>Status:</strong> ${esc(calc.status)}</p>
  <p style="background:#fff3f0;padding:10px;border-radius:6px;font-size:13px;">Legend: <strong>USER INPUT</strong> → <strong>CALCULATED VALUE</strong> → <strong>AI RECOMMENDATION</strong>. Review before procurement.</p>

  <h2>A. Project Summary (User Input)</h2>
  <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;">
    ${kv('Duration (years)', input.duration_years)}
    ${kv('Working days / year', input.working_days)}
    ${kv('Employees', input.employees)}
    ${kv('Shifts', input.shifts)}
    ${kv('Working hours / shift', input.working_hours_per_shift)}
    ${kv('Input image size / day (TB)', input.input_tb_per_day)}
    ${kv('Output image size / day (TB)', input.output_tb_per_day)}
    ${kv('Annual data growth (%)', input.annual_growth_percent)}
    ${kv('Retention (years)', input.retention_years)}
    ${kv('Backup retention (days)', input.backup_retention_days)}
    ${kv('High availability', input.ha_required ? 'Yes' : 'No')}
  </table>

  <h2>B. Data & Storage (Calculated)</h2>
  <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;">
    ${kv('Daily total data (TB)', c.data_analysis.daily_total_data_tb)}
    ${kv('Year 1 annual data (TB)', c.data_analysis.year1_annual_data_tb)}
    ${kv('Project total data (TB)', c.data_analysis.project_total_data_tb)}
    ${kv('Retention storage (TB)', c.data_analysis.retention_storage_tb)}
    ${kv('Usable storage (TB)', c.storage.usable_storage_tb)}
    ${kv('Raw storage (TB)', c.storage.raw_storage_tb)}
    ${kv('Backup storage (TB)', c.storage.backup_storage_tb)}
    ${kv('DR storage (TB)', c.storage.dr_storage_tb)}
    ${kv('Recommended free capacity (%)', c.storage.recommended_free_capacity_percent)}
  </table>

  <h2>C. Compute, Scanners & Network (Calculated)</h2>
  <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;">
    ${kv('Application servers', c.servers.application_servers)}
    ${kv('Database servers', c.servers.database_servers)}
    ${kv('Storage servers', c.servers.storage_servers)}
    ${kv('Processing servers', c.servers.processing_servers)}
    ${kv('Total desktops (incl. spare)', c.desktops.total_desktops)}
    ${kv('Required scanners', c.scanners.required_scanners)}
    ${kv('Total scanners (incl. spare)', c.scanners.total_scanners)}
    ${kv('Scanner capacity sufficient?', c.scanners.scanner_capacity_sufficient ? 'Yes' : 'No — under-provisioned')}
    ${kv('LAN bandwidth', c.network.lan_bandwidth)}
    ${kv('Storage bandwidth', c.network.storage_bandwidth)}
    ${kv('Firewalls', c.firewall.firewalls_required)}
    ${kv('Firewall throughput (Gbps)', c.firewall.recommended_throughput_gbps)}
    ${kv('Estimated load (kW)', c.ups.estimated_load_kw)}
    ${kv('Recommended UPS (kVA)', c.ups.recommended_ups_kva)}
  </table>

  <h2>D. Year-wise Capacity Plan</h2>
  <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;">
    <tr style="background:#f0f0f0;"><th>Year</th><th>Employees</th><th>Daily Data (TB)</th><th>Annual Data (TB)</th><th>Cumulative (TB)</th></tr>
    ${yearRows}
  </table>

  <h2>E. Recommended Hardware BOM (AI)</h2>
  <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:13px;">
    <tr style="background:#f0f0f0;"><th>Category</th><th>Item</th><th>Qty</th><th>Minimum Spec</th><th>Recommended Spec</th><th>Purpose</th><th>Assumption</th></tr>
    ${bomRows || '<tr><td colspan="7">AI recommendations unavailable.</td></tr>'}
  </table>

  <h2>F. Recommendations (AI)</h2>
  <ul>${rows(ai.recommendations) || '<li>Not available</li>'}</ul>
  <h2>G. Assumptions (AI)</h2>
  <ul>${rows(ai.assumptions) || '<li>Not available</li>'}</ul>
  <h2>H. Risks (AI)</h2>
  <ul>${rows(ai.risks) || '<li>Not available</li>'}</ul>
  <h2>I. Capacity Expansion Plan (AI)</h2>
  <ul>${rows(ai.capacity_expansion_plan) || '<li>Not available</li>'}</ul>

  <p style="margin-top:24px;font-size:12px;color:#666;">Generated ${new Date().toISOString()}. Sizing must be validated by the infrastructure team before procurement.</p>
</div>
`;

return [{ json: { reportHtml: html, status: calc.status, input, calculated: c, ai } }];

// ---------- helpers ----------
const src = $input.first().json;
const num = (v, def = 0) => {
  if (v === undefined || v === null || v === '') return def;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? def : n;
};
const yesNo = (v) => String(v || '').trim().toLowerCase() === 'yes';
const round = (n, d = 2) => Math.round((n + Number.EPSILON) * Math.pow(10, d)) / Math.pow(10, d);

// ---------- normalized user input ----------
const input = {
  project_no: src.project_no || '',
  duration_years: Math.max(1, Math.round(num(src.project_duration_years, 1))),
  working_days: Math.max(1, Math.round(num(src.working_days, 250))),
  employees: Math.max(0, Math.round(num(src.employees))),
  shifts: Math.max(1, Math.round(num(src.shifts, 1))),
  working_hours_per_shift: Math.max(1, num(src.working_hours_per_shift, 8)),
  input_tb_per_day: num(src.input_image_size_per_day_tb),
  output_tb_per_day: num(src.output_image_size_per_day_tb),
  annual_growth_percent: num(src.annual_growth_percent, 0),
  retention_years: Math.max(1, Math.round(num(src.retention_years, 1))),
  backup_retention_days: Math.max(1, Math.round(num(src.backup_retention_days, 30))),
  num_scanners: Math.round(num(src.num_scanners)),
  scanner_images_per_day: Math.round(num(src.scanner_images_per_day)),
  concurrent_users: Math.round(num(src.concurrent_users)),
  ha_required: yesNo(src.ha_required),
};

// ---------- validation ----------
const missing = [];
if (!input.project_no) missing.push('project_no');
if (input.input_tb_per_day <= 0 && input.output_tb_per_day <= 0) missing.push('image_size_per_day');
if (input.employees <= 0) missing.push('employees');

// ---------- data calculations ----------
const dailyTotalTb = input.input_tb_per_day + input.output_tb_per_day;
const growth = input.annual_growth_percent / 100;

// year-wise capacity (growth applied year over year)
const yearly = [];
let cumulative = 0;
let dailyForYear = dailyTotalTb;
for (let y = 1; y <= input.duration_years; y++) {
  if (y > 1) dailyForYear = dailyForYear * (1 + growth);
  const annualTb = dailyForYear * input.working_days;
  cumulative += annualTb;
  yearly.push({
    year: y,
    employees: input.employees,
    daily_data_tb: round(dailyForYear, 3),
    annual_data_tb: round(annualTb, 2),
    cumulative_data_tb: round(cumulative, 2),
  });
}
const projectTotalTb = cumulative;
const year1AnnualTb = yearly[0].annual_data_tb;

// retention storage = data kept during the most recent retention window
const retentionWindow = Math.min(input.retention_years, input.duration_years);
const retentionStorageTb = yearly
  .slice(-retentionWindow)
  .reduce((s, y) => s + y.annual_data_tb, 0);

// growth capacity = extra to accommodate future growth headroom
const growthStorageTb = retentionStorageTb * growth;

// ---------- storage sizing ----------
const FREE_CAPACITY_PCT = 0.30;      // keep 30% operational free space
const RAID_EFFICIENCY = 0.80;        // RAID6 usable ratio (approx)
const OVERHEAD_FACTOR = 1.15;        // filesystem + metadata + snapshot + temp
const usableStorageTb = (retentionStorageTb + growthStorageTb) * OVERHEAD_FACTOR / (1 - FREE_CAPACITY_PCT);
const rawStorageTb = usableStorageTb / RAID_EFFICIENCY;
const expansionCapacityTb = usableStorageTb * 0.5; // room to grow

// ---------- backup & DR ----------
const backupCopies = 2;
const backupCompression = 0.6; // 40% saving
const backupStorageTb = retentionStorageTb * backupCopies * backupCompression;
const drStorageTb = usableStorageTb; // one DR replica of usable

// ---------- server sizing ----------
const effConcurrent = input.concurrent_users > 0 ? input.concurrent_users : Math.ceil(input.employees / Math.max(1, input.shifts));
const imageProcessing = dailyTotalTb > 0;
const appServers = Math.max(input.ha_required ? 2 : 1, Math.ceil(effConcurrent / 75));
const dbServers = input.ha_required ? 2 : 1;
const storageServers = input.ha_required ? 2 : 1;
const processingServers = imageProcessing ? (input.ha_required ? 2 : 1) : 0;

// ---------- desktops ----------
const productionDesktops = Math.max(effConcurrent, Math.ceil(input.employees / Math.max(1, input.shifts)));
const spareDesktops = Math.ceil(productionDesktops * 0.10);

// ---------- scanners ----------
const SCANNER_THROUGHPUT_IPM = 40;        // images per minute assumption
const SCANNER_EFFICIENCY = 0.70;          // duty cycle
const availableScanMinutes = input.shifts * input.working_hours_per_shift * 60 * SCANNER_EFFICIENCY;
const scannerCapacityPerDay = SCANNER_THROUGHPUT_IPM * availableScanMinutes;
const requiredScanners = input.scanner_images_per_day > 0
  ? Math.ceil(input.scanner_images_per_day / scannerCapacityPerDay)
  : input.num_scanners;
const spareScanners = Math.max(1, Math.ceil(requiredScanners * 0.10));

// ---------- network ----------
const peakThroughputGbps = dailyTotalTb / (input.working_hours_per_shift * input.shifts * 3600) * 8 * 1000; // TB/day -> Gbps rough
let lanBandwidth = '1 Gbps';
if (peakThroughputGbps > 1) lanBandwidth = '10 Gbps';
if (dailyTotalTb >= 2) lanBandwidth = '10 Gbps';
const serverBandwidth = dailyTotalTb >= 1 ? '10 Gbps' : '1 Gbps';
const storageBandwidth = dailyTotalTb >= 2 ? '25 Gbps' : '10 Gbps';
const switchPorts = productionDesktops + spareDesktops + requiredScanners + spareScanners + (appServers + dbServers + storageServers + processingServers) * 2 + 10;

// ---------- firewall ----------
const fwThroughputGbps = Math.max(1, Math.ceil((effConcurrent / 50) + (dailyTotalTb)));
const firewalls = input.ha_required ? 2 : 1;

// ---------- UPS / power ----------
const serverCount = appServers + dbServers + storageServers + processingServers;
const estimatedLoadKw = round(
  serverCount * 0.5 +
  (productionDesktops + spareDesktops) * 0.2 +
  (requiredScanners + spareScanners) * 0.1 +
  firewalls * 0.15 +
  1.0, // switches/misc
  2,
);
const upsKva = round(estimatedLoadKw / 0.8 * 1.5, 2); // power factor 0.8, 1.5x redundancy/headroom

const calculated = {
  data_analysis: {
    daily_input_data_tb: round(input.input_tb_per_day, 3),
    daily_output_data_tb: round(input.output_tb_per_day, 3),
    daily_total_data_tb: round(dailyTotalTb, 3),
    year1_annual_data_tb: round(year1AnnualTb, 2),
    project_total_data_tb: round(projectTotalTb, 2),
    retention_storage_tb: round(retentionStorageTb, 2),
    growth_storage_tb: round(growthStorageTb, 2),
  },
  storage: {
    raw_storage_tb: round(rawStorageTb, 2),
    usable_storage_tb: round(usableStorageTb, 2),
    recommended_free_capacity_percent: FREE_CAPACITY_PCT * 100,
    raid_efficiency: RAID_EFFICIENCY,
    expansion_capacity_tb: round(expansionCapacityTb, 2),
    backup_storage_tb: round(backupStorageTb, 2),
    dr_storage_tb: round(drStorageTb, 2),
  },
  servers: {
    application_servers: appServers,
    database_servers: dbServers,
    storage_servers: storageServers,
    processing_servers: processingServers,
    image_processing_required: imageProcessing,
    effective_concurrent_users: effConcurrent,
  },
  desktops: {
    production_desktops: productionDesktops,
    spare_desktops: spareDesktops,
    total_desktops: productionDesktops + spareDesktops,
  },
  scanners: {
    scanner_capacity_per_day: Math.round(scannerCapacityPerDay),
    required_scanners: requiredScanners,
    spare_scanners: spareScanners,
    total_scanners: requiredScanners + spareScanners,
    user_planned_scanners: input.num_scanners,
    scanner_capacity_sufficient: input.num_scanners >= requiredScanners,
  },
  network: {
    lan_bandwidth: lanBandwidth,
    server_bandwidth: serverBandwidth,
    storage_bandwidth: storageBandwidth,
    estimated_switch_ports: switchPorts,
  },
  firewall: {
    firewalls_required: firewalls,
    ha_required: input.ha_required,
    recommended_throughput_gbps: fwThroughputGbps,
  },
  ups: {
    estimated_load_kw: estimatedLoadKw,
    recommended_ups_kva: upsKva,
  },
  yearly_capacity: yearly,
};

const status = missing.length > 0 ? 'NEEDS_INFORMATION' : 'SUCCESS';

return [{
  json: {
    status,
    missing_fields: missing,
    input,
    calculated,
    ai_payload: JSON.stringify({ input, calculated }, null, 2),
  },
}];
